/** @param {string} category */
function getBehaviorCategoryIcon(category) {
  /** @type {Record<string, string>} */
  const icons = {
    ['navigation']: '🧭',
    ['content']: '🖥️',
    ['list']: '📃',
    ['form']: '🖋️',
    ['feedback']: '💡',
